import {RULES,BODY_LIMITS} from './model-rules.js';
import {ACTION_DURATIONS,SUBSTEPS,DT} from './action-timing.js';
import {v,p,a,table,details} from './guide-markup.js';

/** Пособие описывает рабочую физику; значения берутся у её владельцев.
 * Здесь нет симуляции и отдельной копии алгоритма усвоения. */
export const GUIDE_FOOD_TEXT={
 'guide-food-path':
 p('Пища проходит несколько разных состояний. На клетке лежат порции; после сбора порция находится в инвентаре. Еда переносит её содержимое в желудок, и только усвоение постепенно пополняет запас энергии тела. Поэтому житель может иметь пищу при себе и всё ещё оставаться без энергии.')
 +'<figure><figcaption>Путь пищи</figcaption><p>Клетка → <strong>сбор</strong> → инвентарь → <strong>еда</strong> → желудок → <strong>усвоение</strong> → энергия тела</p></figure>'
 +table('Что именно измеряется',['Место','Единица и предел','Как меняется'],[
 ['Клетка','порции','Сбор уменьшает запас; источник и выкладывание могут его пополнять.'],
 ['Инвентарь',v(RULES.inventoryCapacity,'порции'),'Переносимый запас; сам по себе энергии не даёт.'],
 ['Желудок',v(RULES.stomachCapacity,'единиц содержимого'),'Одна съеденная порция добавляет '+v(RULES.foodEnergy)+'.'],
 ['Тело',v(BODY_LIMITS.energy,'энергии'),'Получает усвоенное содержимое и оплачивает деятельность и мышление.']])
 +p(`Время усвоения одной порции в выбранном контексте — <span class="guide-value" data-guide-param="digestionTime">${RULES.foodEnergy/RULES.digestionRate} Т</span>. Это длительность переработки содержимого порции при непрерывном усвоении, а не длительность действия «Еда». Настройка меняет скорость усвоения, сохраняя энергоценность порции.`)
 +'<h4>Пример: житель подобрал порцию</h4><ol>'
 +`<li>На текущей клетке есть пища, а в инвентаре свободно. Завершив сбор за ${v(ACTION_DURATIONS[6]/SUBSTEPS,'Т')}, житель переносит одну порцию с клетки в инвентарь.</li>`
 +`<li>Если в желудке есть место для целой порции, житель может выбрать еду. Через ${v(ACTION_DURATIONS[7]/SUBSTEPS,'Т')} порция исчезает из инвентаря, а желудок получает ${v(RULES.foodEnergy,'единиц содержимого')}.</li>`
 +`<li>Усвоение этой порции начинается со следующего подшага. На каждом подшаге длительностью ${v(DT,'Т')} часть содержимого покидает желудок и пополняет энергию — насколько позволяет свободное место в теле.</li></ol>`
 +p('Если перед усвоением энергия уже заполнена, соответствующее содержимое желудка всё равно расходуется, но не прибавляется к энергии. Следующий в этом же подшаге расход деятельности уже не возвращает эту потерянную часть. Порядок важен: сначала усвоение, затем расход, затем завершение еды.')
 +details('Условия, завершение и конкуренция',
 p(`Для начала сбора требуется пища на текущей клетке и инвентарь меньше ${v(RULES.inventoryCapacity,'порций')}. Для еды нужна порция в инвентаре и не менее ${v(RULES.foodEnergy,'единиц')} свободного места в желудке. Эти условия повторно проверяются при завершении.`)
 +p('Начало сбора не резервирует порцию. Если несколько жителей завершают сбор на одной клетке одновременно, а порций меньше, порядок разыгрывается случайно. Успешные сборы уменьшают запас; тем, кому уже не хватило пищи, записывается физический срыв.')
 +p('При смене действия до завершения порция ещё не переносится. Потраченное время и уже оплаченная энергия остаются расходом. Если житель погибает, завершения не происходит. Продолжение того же процесса сохраняет его прогресс; подробности приведены в главе действий.')
 +p('За подшаг усваивается не больше остатка в желудке и не больше произведения скорости усвоения на длительность подшага. В тело попадает только то, что помещается до верхней границы энергии. Переполнение отдельно учитывается как потеря. Еда не восстанавливает здоровье напрямую.'))
 +p(`Дальше: ${a('deposits','выкладывание пищи')}, ${a('energy','расходы и дефицит')}, ${a('actions','действия и прерывания')}, ${a('environment','изменение источников')}.`),
 'guide-food-deposits':
 p('Выкладывание переносит порцию из инвентаря на текущую клетку суши. Её сможет собрать любой житель. Пища не получает владельца, а источник от такого действия не возникает: меняется запас, а не способность клетки производить новые порции.')
 +p(`Действие занимает ${v(ACTION_DURATIONS[10]/SUBSTEPS,'Т')}. Оно доступно живому жителю с непустым инвентарём, пока на клетке меньше ${v(RULES.groundFoodCapacity,'порций')}. При завершении условия проверяются ещё раз, затем инвентарь уменьшается на порцию, а запас клетки увеличивается.`)
 +'<h4>Пример: запас без источника</h4>'
 +p('Житель оставил порцию на пустой клетке и ушёл. Порция остаётся там до сбора; собственного расписания пополнения у неё нет. Другой житель может подобрать её, перенести и съесть обычным способом. Если позже на клетке появится источник, его производство будет работать уже по правилам среды.')
 +details('Два разных ограничения запаса',
 p(`Порог ${v(RULES.groundFoodCapacity,'порций')} ограничивает только выкладывание. У источника есть собственная вместимость для пополнения. Поэтому уже лежащая пища может превышать порог выкладывания или новую уменьшенную вместимость источника: эти правила не обрезают существующий запас.`)
 +p('Выложенная пища не является остатком погибшего тела. При гибели содержимое инвентаря списывается в потери пищи; энергия тела и желудка — в отдельные потери энергии. Запас клетки от гибели не увеличивается. Ранее оставленные порции сохраняются независимо от жизни оставившего их жителя.'))
 +p(`Связанные темы: ${a('food','путь пищи')}, ${a('energy','гибель и ресурсы')}, ${a('environment','перенос источников')}.`),
};
